1: /**
2:  * Onboard Progress
3:  *
4:  * Onboard Progress (level) Indicator
5:  */
6: import React, { useState } from "react";
7: import PT from "prop-types";
8: import cn from "classnames";
9: import "./styles.module.scss";
10: import ProgressDonutChart from "components/ProgressDonutChart";
11: import ProgressPopup from "components/ProgressPopup";
12: import IconThreeDots from "../../assets/images/icon-three-dots-vertical.svg";
13: import IconCrossGreen from "../../assets/images/icon-cross-green.svg";
14: import config from "../../../config";
15: import { ProgressLevels as levels, MAX_COMPLETED_STEP } from "constants";
16: import _ from "lodash";
17: 
18: const OnboardProgress = ({ level, styleName, handleSubmit, ...props }) => {
19:   const [progressPopupOpen, setProgressPopupOpen] = useState(false);
20:   const maxCompletedStep = localStorage.getItem(MAX_COMPLETED_STEP) || 0;
21:   const redirectUrl = config.TOPCODER_COMMUNITY_WEBSITE_URL + "/home";
22: 
23:   if (
24:     _.isUndefined(maxCompletedStep) ||
25:     _.isNull(maxCompletedStep) ||
26:     parseInt(maxCompletedStep) < level
27:   ) {
28:     localStorage.setItem(MAX_COMPLETED_STEP, level);
29:   }
30: 
31:   return (
32:     <div styleName={cn("onboard-progress", styleName || "")} {...props}>
33:       <div styleName="level-container">
34:         <div styleName="level">
35:           <span styleName="level-num">STEP {level} </span>
36:           <span styleName="muted">/ {levels.length}</span>
37:         </div>
38:         <div>{levels[level - 1].label}</div>
39:       </div>
40:       <ProgressDonutChart
41:         styleName="progress-donut-chart"
42:         progress={100 * (level / levels.length)}
43:       />
44:       <a
45:         href={redirectUrl}
46:         onClick={(e) => {
47:           e.preventDefault();
48:           handleSubmit(e, true);
49:         }}
50:         styleName="cancel-onboard"
51:       >
52:         <IconCrossGreen />
53:       </a>
54:       <div
55:         styleName="progress-popup-toggle"
56:         onClick={(e) => setProgressPopupOpen((o) => !o)}
57:       >
58:         <IconThreeDots />
59:       </div>
60:       <ProgressPopup
61:         level={level}
62:         maxStep={maxCompletedStep}
63:         levels={levels}
64:         open={progressPopupOpen}
65:         handleClose={(e) => setProgressPopupOpen(false)}
66:       />
67:     </div>
68:   );
69: };
70: 
71: OnboardProgress.propTypes = {
72:   handleSubmit: PT.func,
73:   level: PT.number,
74: };
75: 
76: export default OnboardProgress;

